use std::io::Write;

const SHADER: &str = r#"
struct Dims { w: u32, h: u32 }
@group(0) @binding(0) var<storage, read> src: array<u32>;
@group(0) @binding(1) var<storage, read_write> dst: array<u32>;
@group(0) @binding(2) var<uniform> dims: Dims;

@compute @workgroup_size(16, 16)
fn main(@builtin(global_invocation_id) id: vec3<u32>) {
    if (id.x >= dims.w || id.y >= dims.h) { return; }
    let x = id.x;
    let y = id.y;
    let l = select(x - 1u, x, x == 0u);
    let r = select(x + 1u, x, x + 1u >= dims.w);
    let u = select(y - 1u, y, y == 0u);
    let d = select(y + 1u, y, y + 1u >= dims.h);
    let s = src[y * dims.w + x] * 4u + src[y * dims.w + l] + src[y * dims.w + r]
        + src[u * dims.w + x] + src[d * dims.w + x];
    dst[y * dims.w + x] = s / 8u;
}
"#;

fn parse(path: &str) -> Result<(usize, usize, usize, Vec<u32>), String> {
    let text = std::fs::read_to_string(path).map_err(|e| e.to_string())?;
    let mut it = text.split_ascii_whitespace();
    let mut next = || -> Result<u64, String> {
        it.next()
            .ok_or_else(|| "unexpected end of input".to_string())?
            .parse::<u64>()
            .map_err(|e| e.to_string())
    };
    let w = next()? as usize;
    let h = next()? as usize;
    let steps = next()? as usize;
    if w == 0 || h == 0 || w > 512 || h > 512 {
        return Err("bad dimensions".into());
    }
    let mut cells = Vec::with_capacity(w * h);
    for _ in 0..w * h {
        cells.push(next()? as u32);
    }
    Ok((w, h, steps, cells))
}

fn run(w: usize, h: usize, steps: usize, cells: &[u32]) -> Result<Vec<u32>, String> {
    if steps == 0 {
        return Ok(cells.to_vec());
    }
    let instance = wgpu::Instance::new(wgpu::InstanceDescriptor::new_without_display_handle());
    let adapter = pollster::block_on(instance.request_adapter(&wgpu::RequestAdapterOptions::default()))
        .map_err(|e| format!("no adapter: {e}"))?;
    let (device, queue) = pollster::block_on(adapter.request_device(&wgpu::DeviceDescriptor::default()))
        .map_err(|e| format!("no device: {e}"))?;

    let size = (w * h * 4) as u64;
    let bytes: Vec<u8> = cells.iter().flat_map(|v| v.to_le_bytes()).collect();
    let storage = wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC | wgpu::BufferUsages::COPY_DST;
    let mk = |label| {
        device.create_buffer(&wgpu::BufferDescriptor {
            label: Some(label),
            size,
            usage: storage,
            mapped_at_creation: false,
        })
    };
    let bufs = [mk("a"), mk("b")];
    queue.write_buffer(&bufs[0], 0, &bytes);
    let dim_bytes: Vec<u8> = [w as u32, h as u32, 0, 0].iter().flat_map(|v| v.to_le_bytes()).collect();
    let dims = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("dims"),
        size: 16,
        usage: wgpu::BufferUsages::UNIFORM | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });
    queue.write_buffer(&dims, 0, &dim_bytes);
    let readback = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("readback"),
        size,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });

    let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: Some("heat"),
        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });
    let pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
        label: Some("heat"),
        layout: None,
        module: &module,
        entry_point: Some("main"),
        compilation_options: Default::default(),
        cache: None,
    });
    let layout = pipeline.get_bind_group_layout(0);
    let groups: Vec<wgpu::BindGroup> = (0..2)
        .map(|i| {
            device.create_bind_group(&wgpu::BindGroupDescriptor {
                label: None,
                layout: &layout,
                entries: &[
                    wgpu::BindGroupEntry { binding: 0, resource: bufs[i].as_entire_binding() },
                    wgpu::BindGroupEntry { binding: 1, resource: bufs[1 - i].as_entire_binding() },
                    wgpu::BindGroupEntry { binding: 2, resource: dims.as_entire_binding() },
                ],
            })
        })
        .collect();

    let mut encoder = device.create_command_encoder(&Default::default());
    for s in 0..steps {
        let mut pass = encoder.begin_compute_pass(&Default::default());
        pass.set_pipeline(&pipeline);
        pass.set_bind_group(0, &groups[s % 2], &[]);
        pass.dispatch_workgroups(w.div_ceil(16) as u32, h.div_ceil(16) as u32, 1);
    }
    encoder.copy_buffer_to_buffer(&bufs[steps % 2], 0, &readback, 0, size);
    queue.submit([encoder.finish()]);

    let slice = readback.slice(..);
    let (tx, rx) = std::sync::mpsc::channel();
    slice.map_async(wgpu::MapMode::Read, move |r| {
        let _ = tx.send(r);
    });
    device
        .poll(wgpu::PollType::wait_indefinitely())
        .map_err(|e| format!("poll: {e}"))?;
    rx.recv().map_err(|e| e.to_string())?.map_err(|e| e.to_string())?;
    let data = slice.get_mapped_range();
    Ok(data
        .chunks_exact(4)
        .map(|c| u32::from_le_bytes([c[0], c[1], c[2], c[3]]))
        .collect())
}

fn main() {
    let path = match std::env::args().nth(1) {
        Some(p) => p,
        None => {
            eprintln!("usage: heat <file>");
            std::process::exit(1);
        }
    };
    let result = parse(&path).and_then(|(w, h, steps, cells)| {
        let out = run(w, h, steps, &cells)?;
        Ok((w, out))
    });
    match result {
        Ok((w, out)) => {
            let mut s = String::new();
            for row in out.chunks(w) {
                let line: Vec<String> = row.iter().map(|v| v.to_string()).collect();
                s.push_str(&line.join(" "));
                s.push('\n');
            }
            let sum: u64 = out.iter().map(|&v| v as u64).sum();
            s.push_str(&format!("SUM {sum}\n"));
            std::io::stdout().write_all(s.as_bytes()).unwrap();
        }
        Err(e) => {
            eprintln!("error: {e}");
            std::process::exit(1);
        }
    }
}
